parameters.jsCode:
const input = $input.first().json;

const data = input.callback_query.data;

const [decision_id, action, selected_option] = data.split('|');

return [
  {
    json: {
      decision_id: decision_id,
      action: action,
      selected_option: selected_option
    }
  }
];

const input = $input.first().json;

// ---------------------------------------------
// 1. Read carrier schedules
// ---------------------------------------------
const carrierSchedules = input.Carrier_Schedules ?? {};

// ---------------------------------------------
// 2. Flatten schedules across all carriers
// ---------------------------------------------
const flattenedSchedules = [];

for (const [carrierName, schedules] of Object.entries(carrierSchedules)) {

  if (!Array.isArray(schedules)) {
    continue;
  }

  for (const schedule of schedules) {

    flattenedSchedules.push({
      ...schedule,

      // Add Carrier only if it is not already provided
      Carrier: schedule.Carrier ?? carrierName
    });
  }
}

// ---------------------------------------------
// 3. Return Strategy-Agent-friendly structure
// ---------------------------------------------
return [
  {
    json: {
      "Carrier agent": flattenedSchedules,

      "Request_Summary": input.Request_Summary ?? null,

      "Filter_Metadata": input.Filter_Metadata ?? null
    }
  }
];

const input = $input.first().json;

return [
  {
    json: input.output ?? input
  }
];

